30,1","-300,0,1","-300,0,1","-300,0,1",false,false,false,false,false,false,false,false,false,false,false,2208,836,389,653,202,3010,3483,707,530,2902,"ling_xr"},h)g[407504]=b({e[9044],407504,19,39,359,"「潜入に最適な恰好してても、満月の夜だとバレるんだな。\nはぁ……めんど。\nでも、アンタに怪我がなくて良かった。\nこっからは、俺たちが反撃に打って出る番だ。」",200075,2,"deco/character/ling_gf",0,false,false,false,false,false,false,false,false,false,false,false,false,"ling_gf"},h)g[407601]=b({e[25033],407601,false,155,360,false,200076,false,"deco/character/dongchengxuanyin",302002,60,1,false,1,false,-290,"1",false,false,false,false,false,false,false,"0,250,1","-140,0,1",1927,862,392,1137,265,2018,3266,1137,557,2018},h)g[407602]=b({e[14034],407602,1,4,361,"「『旦那さんにとって、うちは所詮ただの一匹の狐。他の狐とさして変わらんかもしれまへん。けど、旦那さんがうちを選んで、飼ってくれたからには、お互いに唯一無二の存在になっていくもんどす。』\n……どうどす？　本に書いてあったこのセリフは。\n……ふふっ、そうどすか。けどうちは、『飼う』という言葉はどうにも好きになれまへん。旦那さんにとっての唯一の存在になる方法は、他にいくらでもおますのになあ。」",200076,1,"deco/character/407602",302002,60,false,false,1,1912,907,392,687,377,3049,2991,761,602,2901,false,2,6474,5000,3107,5430,6666,6666,6666,6666,10000,13333,6666,false,false,0},h)